WFJ.Data.add("quest", {
  [98024] = { "Viaggio al ⟦Crossroads=Crocevia⟧", "Presentati a Thork al ⟦The Crossroads=Crocevia⟧, nelle ⟦The Barrens=Savane⟧.", "Dopo il viaggio fin qui dal piano elementale, i problemi delle nostre terre potranno sembrarti piccoli. Ma stai pur cert<o/a> che i pericoli che l'Orda affronta sono più che reali, e diventerai formidabile se sopravvivrai al tuo servizio.\n\nSe vuoi cominciare a fare un po' di bene nel nostro mondo, viaggia a sud-ovest verso le vaste terre chiamate ⟦Barrens=Savane⟧. Lì c'è un insediamento noto come il ⟦Crossroads=Crocevia⟧. I suoi fieri abitanti hanno sempre bisogno di aiuto.\n\nVa' con onore, <avventuriero/avventuriera>!", nil, "Che cos'è questo? Un elfo? E dici che ti ha mandato il Capoguerra?\n\n<Thork grugnisce bruscamente squadrandoti da capo a piedi.>\n\nMi sembri un po' mingherlin<o/a>, ma non importa. Qui fuori o prosperi e sopravvivi, o muori. Così vanno le cose in queste terre.", 0xeac1fba3, 0x0ce1d543, 0x7fd58f06, nil, 0xd7076b4c, "...m." },
  [98046] = { "La corona della terra", nil, nil, nil, nil, 0x6a9c354f, nil, nil, nil, nil, ".mmmm" },
  [98065] = { "La corona della terra", nil, nil, nil, nil, 0x6a9c354f, nil, nil, nil, nil, ".mmmm" },
  [98189] = { "La restituzione della statuetta", nil, nil, nil, nil, 0x6359787c, nil, nil, nil, nil, ".mmmm" },
  [98284] = { "Campeggio 101: Incantamento", nil, "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Enchanted Lute per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [98285] = { "Campeggio 101: Ingegneria", nil, nil, nil, nil, 0x1cb4025b, nil, nil, nil, nil, ".mmmm" },
  [98286] = { "Campeggio 101: Incantamento", nil, "Gli incantatori rendono migliore ogni cosa e sono sempre i benvenuti in qualsiasi accampamento nelle terre selvagge.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Enchanted Lute per il tuo accampamento. È importantissimo trovare un po' di svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere pront<o/a> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, nil, 0xb4a29ffc, nil, nil, ".m.mm" },
  [98287] = { "Campeggio 101: Ingegneria", "Parla con Sprite Jumpsprocket a ⟦Stormwind=Roccavento⟧ per imparare a creare un oggetto da campeggio per la tua professione, quando avrai dimostrato abbastanza abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Reagent Bot per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [98298] = { "La follia di Arugal", "Porta $N1 Worgen Bits a Dalar Dawnweaver, alla ⟦The Sepulcher=Mausolea⟧.", "Ah, ora è tutto così imbarazzantemente chiaro! Arugal non aveva quasi nessuna magia, figuriamoci abbastanza da creare i worgen. La ⟦Arugal's Curse=Maledizione di Arugal⟧. Pah! Era a malapena abbastanza potente da durare qualche secondo.\n\nQueste catene dimostrano che sa vincolare le bestie, non crearle. È evidente che i worgen diffondono la maledizione in un altro modo. Voglio sapere come.\n\nVa' al Greymane Wall, a sud. Pare che i worgen si stiano diffondendo tra gli umani dei dintorni. Fai a pezzi le bestie e portami tutto ciò che trovi. Qui serve un approccio più diretto.", "Zanne, artigli, ventrigli. Per me non fa differenza. Il modo più semplice di studiare qualcosa è vederne le budella con i propri occhi.", "Pare che alla fine rida bene chi ride ultimo, ah ah! Arugal era davvero uno sciocco. E io, Dalar Dawnweaver, l'ho smascherato per l'impostore che è.\n\nQuesti pezzi sono tutte le prove che mi servono: la maledizione non ha niente a che fare con quell'idiota farneticante.\n\nPurtroppo, questo significa che anche il suo rimedio non vale niente. Pare che la ricerca di una soluzione alla maledizione dei worgen continui.", 0x93f7323d, 0x865fabf6, 0x0e0f701a, 0xc3554411, 0x385eae60, "....." },
  [98340] = { "Il Grande Spirito Felino", "Parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Sembra che tu sia <pronto/pronta> per il prossimo passo del tuo viaggio, giovane druido. Dendrite Starblaze ti ha mandato a chiamare e desidera che tu vada di nuovo a cercarlo a ⟦Moonglade=Radaluna⟧.\n\nHai già imparato a invocare la magia che ti porta a ⟦Moonglade=Radaluna⟧, quindi puoi partire subito, se vuoi. Ti suggerirei di andare presto, se desideri proseguire il tuo addestramento druidico.", nil, nil, 0xb22fd0a9, 0x127a78ca, 0xe8864144, nil, nil, "...mm" },
  [98342] = { "Il Grande Spirito Felino", nil, nil, nil, nil, 0xb22fd0a9, nil, nil, nil, nil, ".mmmm" },
  [98362] = { "Verso ⟦Thunder Bluff=Picco del Tuono⟧", "Torna a ⟦Thunder Bluff=Picco del Tuono⟧ e parla con Turak Runetotem sull'⟦Elder Rise=Altura degli Anziani⟧.", "È giunto il momento di separarci ancora una volta, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Sembra che il tuo istruttore, Turak Runetotem, abbia trovato in te un allievo degno. Credo di vederlo anch'io. Segui le sue lezioni e presto potrai attingere al Grande Spirito Felino per assumerne la forma.\n\nTorna da dove sei venut<o/a>. Quando sarà il momento, ci rivedremo.", nil, nil, 0xb1ea6f7d, 0x7484d02e, 0x94e47dad, nil, nil, "...mm" },
  [98386] = { "⟦Alther's Mill=Segheria di Alther⟧", "Uccidi $N1 Greater Tarantula e distruggi $N2 Tarantula Egg alla ⟦Alther's Mill=Segheria di Alther⟧ per il caposquadra Oslow, a ⟦Redridge=Crestarossa⟧.", "Orchi, gnoll, murloc. Sembra che tutto voglia impedirmi di finire questo ponte in tempo. E ora ci arriva voce che la nostra segheria è infestata dalle tarantole!\n\nSe te la senti di guadagnare qualche moneta in più, potresti andare alla ⟦Alther's Mill=Segheria di Alther⟧, a est, e risolvere il loro problema con i ragni? Quel posto per me è praticamente inutile se non posso mandarci gli operai a ritirare i carichi in sicurezza.\n\nAh, e se vedi il vecchio Alther, digli che mi deve un favore per aver ripulito il suo pasticcio.", nil, "La segheria è messa così male? È peggio di quanto pensassi.\n\nNon sono particolarmente schizzinoso, ma il lavoro è già abbastanza duro senza ragni che mi portano via gli operai. Grazie dell'aiuto, {name}!", 0xe7ba8f99, 0x7745e897, 0xebb117bb, nil, 0x4d3ec210, "...m." },
  [98393] = { "Il Grande Spirito Felino", "Parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧, a ⟦Moonglade=Radaluna⟧.", "Sembra che tu sia <pronto/pronta> per il prossimo passo del tuo viaggio, giovane druido. Dendrite Starblaze ti ha mandato a chiamare e desidera che tu vada di nuovo a cercarlo a ⟦Moonglade=Radaluna⟧.\n\nHai già imparato a invocare la magia che ti porta a ⟦Moonglade=Radaluna⟧, quindi puoi partire subito, se vuoi. Ti suggerirei di andare presto, se desideri proseguire il tuo addestramento druidico.", nil, nil, 0xb22fd0a9, 0x127a78ca, 0xe8864144, nil, nil, "...mm" },
  [98394] = { "Il Grande Spirito Felino", nil, nil, nil, nil, 0xb22fd0a9, nil, nil, nil, nil, ".mmmm" },
  [98396] = { "Il Grande Spirito Felino", nil, nil, nil, nil, 0xb22fd0a9, nil, nil, nil, nil, ".mmmm" },
  [98397] = { "Verso Darnassus", "Torna a Darnassus e parla con Mathrengyl Bearwalker nell'⟦Cenarion Enclave=Enclave Cenariana⟧.", "È giunto il momento di separarci ancora una volta, giovane, perché mettere in pratica le tue lezioni ti riporta da chi ti ha mandato da me. Sembra che il tuo istruttore, Mathrengyl Bearwalker, abbia trovato in te un allievo degno. Credo di vederlo anch'io. Segui le sue lezioni e presto potrai attingere al Grande Spirito Felino per assumerne la forma.\n\nTorna da dove sei venut<o/a>. Quando sarà il momento, ci rivedremo.", nil, nil, 0xcf1122f7, 0x17d4d4c5, 0x86c4515f, nil, nil, "...mm" },
  [98403] = { "Odio contorto", "Uccidi $N1 Befouled Webwood e porta il Mature Fel Moss di Xethorr il Malvagio a Tallonkai Swiftroot a Dolanaar.", "Lord Melenas non ha agito da solo: era al servizio di un altro. Colui che cerchi è Xethorr il Malvagio. Pare che abbia corrotto i ragni che vivono a Teldrassil, destinando il loro veleno a qualche piano immondo.\n\nSi è stabilito nel profondo della foresta, nella zona a nord-ovest di qui nota come the Cleft. Sii prudente e porta degli alleati, perché Xethorr non è un avversario da prendere alla leggera.\n\nElimina la sua covata e portami qualunque cosa possa dirci di più sulle attività del satiro qui.", "<Tallonkai abbassa la voce.>\n\nXethorr cammina ancora libero?", "Avrei dovuto sapere che questo veniva usato per corrompere i ragni di questa terra.\n\nHo sentito voci secondo cui questa sostanza sarebbe all'origine di gran parte della corruzione che ci affligge. Anche se questo non è l'originale, è un campione più vecchio e potrebbe fornire più informazioni di quante ne abbiamo ottenute finora.\n\nDi solito ti farei mandare questo a Darnassus per ulteriori studi. Tuttavia, per il momento è meglio tenere la cosa sotto silenzio, o Dolanaar non recupererà mai la sua reputazione.\n\nConfido che farai lo stesso.", 0x10738b8e, 0xa891e626, 0x8a01b9a3, 0x32ad7205, 0x7c0c6469, "....." },
  [98405] = { "Il Grande Spirito Felino", nil, nil, nil, nil, 0xb22fd0a9, nil, nil, nil, nil, ".mmmm" },
  [98447] = { "La famiglia Valor", nil, nil, nil, nil, 0x27a57039, nil, nil, nil, nil, ".mmmm" },
  [98517] = { "Il richiamo del fuoco", "Presentati a Sessaria Skystride o ad Aarnor Galestrike sull'isola di Zephras per continuare il tuo addestramento come <Sciamano/Sciamana>.\n\nPuoi tornare a Zephras con il trasporto skycutter che attracca a Mulgore, allo Skywatcher Plateau, a nord-ovest di ⟦Thunder Bluff=Picco del Tuono⟧.", "Salute, giovane Skyborne. Gli spiriti mi hanno parlato di te e mi dicono che sei <pronto/pronta> a rispondere al richiamo del fuoco. Tuttavia, non sarò io a iniziarti su quel sentiero. Torna alla tua casa nel piano elementale e cerca lì i tuoi mentori. Ti diranno cosa deve essere fatto.", nil, nil, 0x53f3b76b, 0xe2cf2544, 0x04034459, nil, nil, "...mm" },
})
